<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';import {descriptionHtml} from './description';
import PmsDescriptionEditor from './PmsDescriptionEditor.vue';
import {ref,onMounted,computed} from 'vue';import {pmsApi} from './api';import PmsSubmissions from './PmsSubmissions.vue';const props=defineProps<{id:number;taskId:number;csrf?:string;permissions:string[]}>();const emit=defineEmits(['close','updated']);const data=ref<any>(null),assignees=ref<any[]>([]),selected=ref(''),busy=ref(false),error=ref(''),description=ref(''),files=ref<File[]>([]);const can=(key:string)=>props.permissions.includes('*')||props.permissions.includes(key);const images=computed(()=>{try{return JSON.parse(data.value?.subtask.images||'[]');}catch{return [];}});async function load(){data.value=await pmsApi('subtasks/'+props.id);description.value=data.value.subtask.description||'';}async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();await load();emit('updated');}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function field(kind:string,value:any){await run(async()=>{const r=await pmsApi('subtask-'+kind,props.csrf,'POST',{sub_task_id:props.id,[kind==='due-date'?'due_date':kind]:value});if(r.success===false)throw Error(r.message);});}
async function title(){await run(async()=>{await pmsApi('subtasks/'+props.id,props.csrf,'PUT',{title:data.value.subtask.title});});}
async function saveDescription(){await run(async()=>{const f=new FormData();f.append('sub_task_id',String(props.id));f.append('description',description.value);files.value.forEach(v=>f.append('attachments[]',v));await pmsApi('subtask-description',props.csrf,'POST',f);files.value=[];});}
async function assignment(action:string,userId:any){await run(async()=>{const r=await pmsApi('task-assignees/'+action,props.csrf,'POST',{task_id:props.taskId,sub_task_id:props.id,subtask_id:props.id,user_id:Number(userId)});if(r.success===false)throw Error(r.message);selected.value='';});}
async function approval(e:Event){await run(async()=>{await pmsApi('subtask-approval',props.csrf,'POST',{subtask_id:props.id,approval:(e.target as HTMLSelectElement).value});});}
async function timer(action:string){await run(async()=>{await pmsApi('timers/'+action,props.csrf,'POST',{task_id:props.taskId,subtask_id:props.id});});}
onMounted(async()=>{await run(load);if(can('task-assign')){try{assignees.value=(await pmsApi('tasks/'+props.taskId+'/assignees')).users;}catch(e){error.value=(e as Error).message;}}});
</script><template><PmsFormDialog title="Subtask details" wide centered @close="emit('close')"><div class="p-4" style="overflow:auto;max-height:75vh"><p v-if="error" class="notice admin-error">{{error}}</p><p v-if="busy">Loading...</p><template v-if="data"><form v-if="can('sub-task-edit')" class="editor-actions" @submit.prevent="title"><label>Title<input v-model="data.subtask.title" required maxlength="255"></label><button class="button" :disabled="busy">Save title</button></form><h3 v-else>{{data.subtask.title}}</h3><div class="editor-actions"><label>Status<select :value="data.subtask.status" :disabled="busy||!can('sub-task-status')" @change="field('status',($event.target as HTMLSelectElement).value)"><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="completed">Completed</option></select></label><label>Priority<select :value="data.subtask.priority" :disabled="busy||!can('sub-task-priority')" @change="field('priority',Number(($event.target as HTMLSelectElement).value))"><option v-for="(p,i) in ['Low','Normal','High','Urgent']" :key="i" :value="i">{{p}}</option></select></label><label>Due date<input type="datetime-local" :value="data.subtask.due_date?.slice(0,16)" :disabled="busy||!can('sub-task-due-date')" @change="field('due-date',($event.target as HTMLInputElement).value)"></label><label v-if="data.can_manage_approvals">Approval<select :value="data.subtask.approval" :disabled="busy" @change="approval"><option value="pending" disabled>Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select></label></div><p>{{data.subtask.approval_note}}</p><form v-if="can('description-update')" @submit.prevent="saveDescription"><label>Description<PmsDescriptionEditor v-model="description"/></label><label>Add images<input type="file" multiple accept="image/*" @change="files=Array.from(($event.target as HTMLInputElement).files||[])"></label><button class="button" :disabled="busy">Save details</button></form><div v-else v-html="descriptionHtml(description)"></div><a v-for="url in images" :key="url" :href="url" target="_blank" rel="noopener"><img :src="url" style="max-width:150px;max-height:100px" alt="Subtask attachment"></a><h3>Assigned employees</h3><div v-for="u in data.subtask.users" :key="u.id" class="row-actions"><span>{{u.name}}</span><button v-if="can('task-assign')" class="button" :disabled="busy" @click="assignment('remove',u.id)">Remove</button></div><form v-if="can('task-assign')" class="editor-actions" @submit.prevent="assignment('assign',selected)"><select v-model="selected" aria-label="Assign employee" required><option value="" disabled>Select employee</option><option v-for="u in assignees" :key="u.id" :value="u.id">{{u.name}}</option></select><button class="button" :disabled="busy||!selected">Assign</button></form><div v-if="data.directly_assigned_to_me" class="editor-actions my-3"><button v-if="!data.own_running_timer&&data.subtask.status!=='completed'" class="button primary" :disabled="busy" @click="timer('start')">Start timer</button><template v-if="data.own_running_timer"><button class="button" :disabled="busy" @click="timer('pause')">Pause timer</button><button class="button" :disabled="busy" @click="timer('stop')">Stop timer</button></template></div><PmsSubmissions type="subtask" :id="id" :csrf="csrf"/></template></div></PmsFormDialog></template>